    fn automation_is_group(&self, agent_id: &str) -> bool {
        if agent_id == "mahayana-assistant" { return false; }
        self.agents.lock().ok().and_then(|agents| agents.get(agent_id)).is_some_and(|agent| agent.is_group)
    }

    fn record_automation_terminal_telemetry(
        &mut self,
        automation_id: &str,
        account_fence: &str,
        started_at_ms: u64,
        updated_at_ms: u64,
        outcome: &str,
    ) {
        let Some(spec) = self.automation_runtime.spec_for_account(automation_id, account_fence) else {
            self.edge_failures.report("automation-runtime", "terminal-telemetry", "MissingSpec");
            return;
        };
        let projection = automation_run_telemetry(&AutomationRunReport {
            conversation_id: spec.agent_id.clone(),
            automation_id: automation_id.to_string(),
            trigger: "schedule".into(),
            outcome: outcome.to_string(),
            is_group: self.automation_is_group(&spec.agent_id),
            duration_ms: updated_at_ms.saturating_sub(started_at_ms) as f64,
            lateness_ms: None,
            scheduled_for_ms: None,
            sent_message_count: None,
            event_batch_size: None,
        });
        self.record_host_telemetry_projection(projection);
    }

    fn record_automation_lifecycle_telemetry(
        &mut self,
        automation_id: &str,
        account_fence: &str,
        action: &str,
    ) {
        let Some(spec) = self.automation_runtime.spec_for_account(automation_id, account_fence) else {
            self.edge_failures.report("automation-runtime", "lifecycle-telemetry", "MissingSpec");
            return;
        };
        let projection = automation_lifecycle_telemetry(&AutomationLifecycleReport {
            conversation_id: spec.agent_id.clone(),
            automation_id: automation_id.to_string(),
            action: action.to_string(),
            source: "android".into(),
            trigger_type: "schedule".into(),
            age_ms: now_ms().saturating_sub(spec.created_at_ms) as f64,
            recorded_run_count: self
                .automation_runtime
                .run_count_for_automation(automation_id, account_fence),
            scheduled_fires_next_7_days: None,
            fires_on_weekend: None,
            fires_overnight: None,
        });
        self.record_host_telemetry_projection(projection);
    }

    fn automation_upsert(&mut self, params: &Value) -> Result<Value, String> {
        let account_fence = self.current_turn_account_fence()?;
        let agent_id = required_string(params, "agentId")?.trim();
        if agent_id != "mahayana-assistant" {
            let agents = self
                .agents
                .lock()
                .map_err(|_| "canonical Android Agent roster lock poisoned".to_string())?;
            if agents.get(agent_id).is_none() {
                return Err("automation agent owner not found".into());
            }
        }
        let trigger = params.get("trigger").cloned().filter(|value| !value.is_null());
        let schedule = params
            .get("schedule")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string();
        let trigger_description = params
            .get("triggerDescription")
            .and_then(Value::as_str)
            .filter(|value| !value.trim().is_empty())
            .map(str::to_string)
            .unwrap_or_else(|| {
                if !schedule.trim().is_empty() {
                    schedule.clone()
                } else {
                    trigger
                        .as_ref()
                        .and_then(|value| value.get("type"))
                        .and_then(Value::as_str)
                        .map(|kind| format!("{kind} event"))
                        .unwrap_or_else(|| "Event trigger".to_string())
                }
            });
        let local_id = required_string(params, "id")?.to_string();
        let id = stable_account_automation_id(&account_fence, agent_id, &local_id);
        let existed = self.automation_runtime.has_owned_spec(&id, &account_fence, agent_id);
        let spec = AutomationSpec {
            id: id.clone(),
            name: required_string(params, "name")?.to_string(),
            prompt: required_string(params, "prompt")?.to_string(),
            schedule,
            trigger,
            agent_id: agent_id.to_string(),
            trigger_description,
            enabled: params.get("enabled").and_then(Value::as_bool).unwrap_or(true),
            account_fence: account_fence.clone(),
            created_at_ms: params.get("createdAtMs").and_then(Value::as_u64).unwrap_or_else(now_ms),
            last_run_at_ms: params.get("lastRunAtMs").and_then(Value::as_u64),
            next_run_at_ms: None,
        };
        let time_zone = self.effective_time_zone()?;
        let listener_platforms = spec.trigger.as_ref().map(trigger_listener_platforms).unwrap_or_default();
        let listener_enabled = spec.enabled;
        self.automation_runtime.upsert_spec(spec, time_zone.as_deref())?;
        if listener_enabled && !listener_platforms.is_empty() {
            let surfaced = surface_listener_connect_cards(
                &listener_platforms,
                Some(|platform: &str| -> Result<bool, String> {
                    self.listener_platform_connected(&account_fence, agent_id, platform)
                }),
                |platform| match platform {
                    "slack" => Some("Slack".to_string()),
                    "github" => Some("GitHub".to_string()),
                    _ => None,
                },
            );
            for card in surfaced.cards {
                let entry_id = format!("automation-listener-connect:{id}:{}", card.platform);
                self.transcript
                    .lock()
                    .map_err(|_| "transcript lock poisoned".to_string())?
                    .append_entry_if_absent(json!({
                        "id":entry_id,
                        "kind":"send-message",
                        "role":"assistant",
                        "agentId":agent_id,
                        "accountFence":account_fence,
                        "timestampMs":now_ms(),
                        "message":{
                            "type":card.message_type,
                            "platform":card.platform,
                            "reason":card.reason
                        }
                    }))
                    .map_err(|error| format!("failed to persist listener connect card: {error}"))?;
                self.transcript_extension
                    .event_bridge()
                    .listener_connect_card(agent_id, card.platform.as_str());
                self.listener_connect_watches.watch(
                    &account_fence,
                    agent_id,
                    card.platform.as_str(),
                    now_ms(),
                )?;
            }
        }
        self.record_automation_lifecycle_telemetry(&id, &account_fence, if existed { "updated" } else { "created" });
        Ok(json!({"id":id,"localId":local_id,"stored":true}))
    }

    fn automation_list(&mut self) -> Result<Value, String> {
        let account_fence = self.current_turn_account_fence()?;
        let time_zone = self.effective_time_zone()?;
        self.automation_runtime.refresh_next_runs(time_zone.as_deref())?;
        Ok(Value::Array(self.automation_runtime.list_for_account(&account_fence)))
    }

    fn automation_list_for_agent(&mut self, params: &Value) -> Result<Value, String> {
        let account_fence = self.current_turn_account_fence()?;
        let agent_id = required_string(params, "agentId")?;
        if agent_id != "mahayana-assistant" {
            let agents = self
                .agents
                .lock()
                .map_err(|_| "canonical Android Agent roster lock poisoned".to_string())?;
            if agents.get(agent_id).is_none() {
                return Err("automation Agent owner not found".into());
            }
        }
        let time_zone = self.effective_time_zone()?;
        self.automation_runtime.refresh_next_runs(time_zone.as_deref())?;
        Ok(Value::Array(
            self.automation_runtime
                .list_for_agent(&account_fence, agent_id),
        ))
    }

