    fn cancel_mcp_auth_watches_for_account_change(
        &mut self,
        reason: &str,
    ) -> Result<(), String> {
        let cancelled_watches = self
            .mcp_auth_watches
            .lock()
            .map_err(|_| "MCP auth watch manager lock poisoned".to_string())?
            .reset_for_account_transition()?;
        for completion in cancelled_watches {
            self.events.push_back(json!({
                "type":"mcp.auth.watch.settled",
                "serverId":completion.server_id,
                "serverName":completion.server_name,
                "accountKey":completion.account_key,
                "requestingAgentId":completion.requesting_agent_id,
                "generation":completion.generation,
                "outcome":"cancelled",
                "reason":reason,
            }));
        }
        Ok(())
    }

    fn fence_turns_for_account_change(
        &mut self,
        previous_fence: &str,
        reason: &str,
    ) -> Result<(), String> {
        let now = now_ms();
        let fenced = self
            .turn_journal
            .lock()
            .map_err(|_| "turn journal lock poisoned".to_string())?
            .mark_account_outcome_unknown(previous_fence, reason, now)?;
        self.turn_lifecycle
            .lock()
            .map_err(|_| "turn lifecycle lock poisoned".to_string())?
            .mark_account_outcome_unknown(previous_fence, now)?;
        let subagent_fenced = self
            .subagent_owner
            .lock()
            .map_err(|_| "subagent owner lock poisoned".to_string())?
            .mark_account_outcome_unknown(previous_fence, reason, now)?;
        if !subagent_fenced.is_empty() {
            let mut events = self
                .subagent_events
                .lock()
                .map_err(|_| "subagent event queue lock poisoned".to_string())?;
            for subagent_id in subagent_fenced {
                events.push_back(json!({
                    "type":"subagent.outcome-unknown",
                    "subagentId":subagent_id,
                    "reason":reason,
                    "accountFence":previous_fence,
                }));
            }
        }

        for record in fenced {
            if let Some(cancelled) = self.turn_cancellations.remove(&record.operation_id) {
                cancelled.store(true, Ordering::Release);
            }
            self.agent_turn_interruptions.unregister_operation(&record.operation_id);
            if let Some(wake_id) = self.agent_wake_operations.remove(&record.operation_id) {
                let _ = self
                    .messaging
                    .lock()
                    .map_err(|_| "canonical Android messaging owner lock poisoned".to_string())?
                    .defer_agent_wake(
                        &wake_id,
                        i64::try_from(now).unwrap_or(i64::MAX),
                        "account-switch",
                    );
            }
            self.active_operations.remove(&record.operation_id);
            push_turn_event(
                &self.turn_events,
                json!({
                    "type":"operation.outcome-unknown",
                    "operationId":record.operation_id,
                    "requestId":record.request_id,
                    "reason":reason,
                    "accountFence":previous_fence,
                }),
            );
        }
        Ok(())
    }

    fn arm_visible_ack_redrives_for_session_change(
        &self,
        previous_fence: Option<&str>,
        current_fence: Option<&str>,
        observed_at_ms: u64,
    ) -> Result<usize, String> {
        let Some(current_fence) = current_fence
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            return Ok(0);
        };
        if previous_fence == Some(current_fence) {
            return Ok(0);
        }
        let transcript_snapshot = self
            .transcript
            .lock()
            .map_err(|_| "transcript lock poisoned while reconciling visible acknowledgements".to_string())?
            .get_transcript();
        self.visible_ack_obligations
            .reconcile_from_transcript(current_fence, &transcript_snapshot)
            .map_err(|error| format!("failed to reconcile visible acknowledgements after session settlement: {error}"))?;
        Ok(self
            .visible_ack_obligations
            .arm_boot_redrives(current_fence, observed_at_ms))
    }

    fn prepare_account_transition_cleanup(
        &mut self,
        previous_fence: &str,
        reason: &str,
    ) -> Result<(), String> {
        fn record_failure(
            failures: &mut Vec<String>,
            owner: &str,
            result: Result<(), String>,
        ) {
            if let Err(error) = result {
                failures.push(format!("{owner}: {error}"));
            }
        }

        let mut failures = Vec::new();

        // Client-side tool identities are account-scoped. Rotate the producer epoch before
        // any transition cleanup can fail so an old-account result can never settle in the
        // next account epoch.
        self.client_side_tool_v2 = ClientSideToolV2Producer::new();

        record_failure(&mut failures, "agent-turns", self.fence_turns_for_account_change(previous_fence, reason));
        record_failure(
            &mut failures,
            "human-calls",
            self.human_calls
                .fence_account(previous_fence, reason, now_ms())
                .map(|_| ()),
        );

        match self.teach_recording.lock() {
            Ok(owner) => {
                let identity = owner.snapshot().clone();
                drop(owner);
                if identity.phase != TeachRecordingPhase::Idle
                    && identity.account_fence.as_deref() == Some(previous_fence)
                {
                    record_failure(
                        &mut failures,
                        "teach-recording",
                        self.teach_recording
                            .lock()
                            .map_err(|_| "Teach Recording owner lock poisoned".to_string())
                            .and_then(|mut owner| owner.fence_account_switch(previous_fence, identity.account_epoch)),
                    );
                }
            }
            Err(_) => failures.push("teach-recording: Teach Recording owner lock poisoned".into()),
        }

        match self.onepassword_provisioning.lock() {
            Ok(owner) => {
                let identity = owner.snapshot().clone();
                drop(owner);
                if matches!(
                    identity.phase,
                    DurableProvisioningPhase::Prepared
                        | DurableProvisioningPhase::Delivering
                        | DurableProvisioningPhase::OutcomeUnknown
                ) && identity.account_fence.as_deref() == Some(previous_fence)
                {
                    record_failure(
                        &mut failures,
                        "onepassword-provisioning",
                        self.onepassword_provisioning
                            .lock()
                            .map_err(|_| "1Password provisioning owner lock poisoned".to_string())
                            .and_then(|mut owner| owner.fence_account_switch(previous_fence, identity.account_epoch)),
                    );
                }
            }
            Err(_) => failures.push(
                "onepassword-provisioning: 1Password provisioning owner lock poisoned".into(),
            ),
        }

        self.pending_plugin_variable_writes.clear();

        if let Some(service) = self.managed_skills.as_ref() {
            record_failure(
                &mut failures,
                "managed-skills",
                service.set_account_scope(None).map_err(|error| {
                    format!("failed to clear managed skills account scope during transition: {error}")
                }),
            );
        }

        record_failure(
            &mut failures,
            "mcp-server-settings",
            self.mcp_server_tool_settings
                .lock()
                .map_err(|_| "MCP server tool settings lock poisoned".to_string())
                .and_then(|mut settings| settings.clear_account(previous_fence)),
        );

        record_failure(
            &mut failures,
            "box-handoff",
            self.box_handoff
                .lock()
                .map_err(|_| "Android box handoff lock poisoned".to_string())
                .and_then(|mut owner| owner.forget_account(previous_fence))
                .map(|_| ()),
        );

        self.experiments.clear_account_scope();

        if let Some(core) = self.cross_user_core.as_ref() {
            record_failure(&mut failures, "cross-user", core.fence_account_transition());
        }

        record_failure(
            &mut failures,
            "mcp-auth-watches",
            self.cancel_mcp_auth_watches_for_account_change(reason),
        );

        record_failure(
            &mut failures,
            "user-settings",
            self.user_settings
                .lock()
                .map_err(|_| "Android user settings lock poisoned".to_string())
                .and_then(|mut settings| {
                    settings.set_local_tool_permission_ceiling(None).map_err(|error| {
                        format!("failed to clear stale local tool permission ceiling: {error}")
                    })
                }),
        );

        if failures.is_empty() {
            Ok(())
        } else {
            Err(format!("account transition cleanup incomplete: {}", failures.join("; ")))
        }
    }


    fn cross_user_fenced<T, F>(&self, operation: F) -> Result<T, String>
    where
        F: FnOnce(&ProductionCrossUserCore) -> Result<T, String>,
    {
        let account_fence = self.current_turn_account_fence()?;
        let core = self
            .cross_user_core
            .as_ref()
            .ok_or("cross-user sharing runtime is unavailable")?;
        core.refresh_self_auth_id()?;
        let gate_enabled = self.experiments.check_feature_gate("sand_multiplayer");
        core.apply_feature_policy(gate_enabled)?;
        let result = operation(core)?;
        if self.current_turn_account_fence()? != account_fence {
            core.fence_account_transition()?;
            return Err("cross-user sharing result is stale after account switch".into());
        }
        Ok(result)
    }

