    fn messaging_contact_groups(&mut self, params: &Value) -> Result<Value, String> {
        let account_scope = self.current_sidebar_account_scope()?;
        let session_fence = self.current_turn_account_fence()?;
        let search_active = params
            .get("searchActive")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let (known_peer_ids, pinned_peer_ids, session_mutation) =
            self.contact_group_projection_inputs()?;
        let snapshot = self
            .contact_groups
            .lock()
            .map_err(|_| "canonical Android contact groups lock poisoned".to_string())?
            .get_snapshot(&account_scope, &known_peer_ids, &pinned_peer_ids, search_active);
        Ok(with_account_session_mutation(
            json!({
                "accountFence":snapshot.account_fence,
                "sessionFence":session_fence,
                "revision":snapshot.revision,
                "groups":snapshot.groups,
            }),
            session_mutation,
        ))
    }

    fn messaging_contact_groups_set(&mut self, params: &Value) -> Result<Value, String> {
        let presentation_fence = required_string(params, "accountFence")?;
        let current_fence = self.current_turn_account_fence()?;
        if presentation_fence != current_fence {
            return Err("contact-group mutation is fenced to a stale account".into());
        }
        let account_scope = self.current_sidebar_account_scope()?;
        let requested_scope = required_string(params, "accountScope")?;
        if requested_scope != account_scope {
            return Err("stale contact-group account scope".into());
        }
        let operation_id = required_string(params, "operationId")?;
        let expected_revision = params
            .get("expectedRevision")
            .and_then(Value::as_u64)
            .ok_or("contact-group expected revision is required")?;
        let groups = params
            .get("groups")
            .and_then(Value::as_array)
            .ok_or("contact groups array is required")?
            .iter()
            .cloned()
            .map(serde_json::from_value::<AndroidContactGroup>)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("invalid contact-group payload: {error}"))?;
        let (known_peer_ids, pinned_peer_ids, session_mutation) =
            self.contact_group_projection_inputs()?;
        let projection = self.contact_groups
            .lock()
            .map_err(|_| "canonical Android contact groups lock poisoned".to_string())?
            .set(
                &account_scope,
                operation_id,
                expected_revision,
                &groups,
                &known_peer_ids,
                &pinned_peer_ids,
            )?;
        Ok(with_account_session_mutation(projection, session_mutation))
    }

    fn agent_sidebar_sections(&mut self) -> Result<Value, String> {
        let account_scope = self.current_sidebar_account_scope()?;
        let known_agent_ids = self
            .agents
            .lock()
            .map_err(|_| "canonical Android Agent roster lock poisoned".to_string())?
            .list()
            .into_iter()
            .map(|agent| agent.id)
            .collect::<BTreeSet<_>>();
        let snapshot = self
            .sidebar_sections
            .lock()
            .map_err(|_| "canonical Android sidebar sections lock poisoned".to_string())?
            .get_snapshot(&account_scope, &known_agent_ids);
        Ok(json!({"accountFence":snapshot.account_fence,"revision":snapshot.revision,"sections":snapshot.sections}))
    }

    fn process_crash_record(&mut self, params: &Value) -> Result<Value, String> {
        let kind = required_string(params, "kind")?;
        if kind != "uncaught_exception" {
            return Err("unsupported Android process crash kind".into());
        }
        let error_class = required_string(params, "errorClass")?;
        if error_class.is_empty()
            || error_class.chars().count() > 96
            || !error_class
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '$'))
        {
            return Err("invalid Android process crash error class".into());
        }
        let occurred_at_ms = required_u64(params, "occurredAtMs")?;
        let uptime_ms = required_u64(params, "uptimeMs")?;

        // The Android platform crash handoff is replayed only after process restart. Attribute
        // that recovered crash to the prior unclean session instead of tainting the newly armed
        // current session marker, which would otherwise create a false crash on the next launch.
        if let Some(previous_unclean) = self.process_crash_recent.iter_mut().rev().find(|entry| {
            entry.get("kind").and_then(Value::as_str) == Some("unclean_exit")
        }) {
            if let Some(record) = previous_unclean.as_object_mut() {
                record.insert("crashSeen".to_string(), Value::Bool(true));
            }
        }

        let bounded_uptime_ms = uptime_ms.min(30 * 24 * 60 * 60 * 1_000_u64);
        let record = json!({
            "kind": kind,
            "errorClass": error_class,
            "occurredAtMs": occurred_at_ms,
            "uptimeMs": bounded_uptime_ms,
            "errorCode": "SAND-E0603",
            "errorDomain": "android-process",
            "errorRetryable": false,
        });
        if self.process_crash_recent.len() >= PROCESS_CRASH_EVENT_CAP {
            self.process_crash_recent.pop_front();
        }
        self.process_crash_recent.push_back(record.clone());

        // Preserve only bounded source-neutral crash metadata. The Android platform handoff never
        // forwards Throwable message/stack/request content, and Host does not read such fields.
        self.sync_structured_log_account_slot();
        let metadata = BTreeMap::from([
            ("kind".to_string(), kind.to_string()),
            ("error_class".to_string(), error_class.to_string()),
            ("error_code".to_string(), "SAND-E0603".to_string()),
            ("error_domain".to_string(), "android-process".to_string()),
            ("uptime_ms".to_string(), bounded_uptime_ms.to_string()),
        ]);
        if self.record_structured_log(
                "error",
                "sand.desktop.process_crash",
                metadata,
                occurred_at_ms,
            )
            .is_err()
        {
            self.edge_failures
                .report("structured-log-spill", "process-crash-record", "StorageError");
        }
        Ok(record)
    }

    fn process_metrics_observe(&mut self, params: &Value) -> Result<Value, String> {
        if !self
            .user_settings
            .lock()
            .map_err(|_| "Android user settings lock poisoned".to_string())?
            .process_metrics_local_enabled()
        {
            return Err("process metrics collection is disabled".into());
        }
        let observed_at_ms = params.get("observedAtMs").and_then(Value::as_u64).ok_or("observedAtMs is required")?;
        let cpu_time_ms_cumulative = params.get("cpuTimeMsCumulative").and_then(Value::as_u64).ok_or("cpuTimeMsCumulative is required")?;
        let memory_bytes = params.get("memoryBytes").and_then(Value::as_u64).ok_or("memoryBytes is required")?;
        let sample = self.process_metrics.observe(observed_at_ms, cpu_time_ms_cumulative, memory_bytes)?;
        let Some(sample) = sample else {
            return Ok(Value::Null);
        };
        let projected = serde_json::to_value(sample)
            .map_err(|error| format!("failed to project Android process metrics: {error}"))?;
        if self.process_metrics_recent.len() >= 32 {
            self.process_metrics_recent.pop_front();
        }
        self.process_metrics_recent.push_back(projected.clone());
        Ok(projected)
    }

    fn box_handoff_resume_prompt(trigger: &str) -> &'static str {
        match trigger {
            "dismissed" => "[The user dismissed your box help request without doing the step you asked for. Treat it as declined: do not assume the step happened, and do not immediately request the box again for the same step. Continue the task without it if you can — skip the step or find another way. If the task cannot proceed without it, send the user a brief message saying what is blocked, then stop and wait for their reply.]",
            "viewer-closed" => "[The user closed the box desktop viewer without explicitly handing control back, so they may or may not have finished the step you asked for. Start with the read-only Screenshot tool to check the current state of the box desktop. If the step is clearly done, continue the task. If you can't tell, send the user a brief message asking whether they finished so you can keep going.]",
            _ => "[The user handed the box back to you. Please continue your task — start with the read-only Screenshot tool to see the current state of the box desktop.]",
        }
    }

    fn sync_subagent_completion_wakes(&mut self) -> Result<(), String> {
        let account_fence = match self.current_turn_account_fence() {
            Ok(value) => value,
            Err(_) => return Ok(()),
        };
        let pending = self
            .subagent_owner
            .lock()
            .map_err(|_| "durable subagent owner lock poisoned".to_string())?
            .pending_completion_wakes_for_account(&account_fence);
        if pending.is_empty() {
            return Ok(());
        }
        let sink = subagent_completion_wake_sink(
            self.pending_wake_store.clone(),
            Arc::clone(&self.subagent_owner),
        );
        for record in pending {
            sink(&record)?;
        }
        Ok(())
    }

    fn subagent_revival_request_id(agent_id: &str, work_ids: &[String]) -> String {
        let mut work_ids = work_ids.to_vec();
        work_ids.sort();
        work_ids.dedup();
        let material = format!("{agent_id}\n{}", work_ids.join("\n"));
        format!(
            "subagent-revival:{}:{}",
            agent_id,
            crate::sha256::sha256_hex(material.as_bytes())
        )
    }

    fn queue_subagent_completion_revival(
        &mut self,
        account_fence: &str,
        agent_id: &str,
        completions: &[SubagentCompletion],
        work_ids: &[String],
    ) -> Result<Option<AccountSessionMutation>, String> {
        if completions.is_empty() || work_ids.is_empty() {
            return Ok(None);
        }
        let request_id = Self::subagent_revival_request_id(agent_id, work_ids);

        // The journal is the idempotency authority. A crash after queue admission but before
        // marker cleanup must converge on the existing turn rather than execute a second model
        // continuation.
        if self
            .turn_journal
            .lock()
            .map_err(|_| "turn journal lock poisoned".to_string())?
            .record(&request_id)
            .is_some()
        {
            for work_id in work_ids {
                self.pending_wake_store.clear_one(
                    account_fence,
                    agent_id,
                    PendingWakeKind::Subagent,
                    work_id,
                );
            }
            return Ok(None);
        }

        let operation_id = self.next_operation_id(&request_id);
        self.active_operations.insert(operation_id.clone());
        let (bearer_token, session_mutation) = match self.bearer_token_for_turn() {
            Ok(value) => value,
            Err(error) => {
                self.active_operations.remove(&operation_id);
                return Err(error);
            }
        };
        let command = json!({
            "type":"chat.send",
            "requestId":request_id,
            "agentId":agent_id,
            "text":build_subagent_revival_prompt(completions),
            "hidden":true,
            "appendUserMessage":false,
            "awaitTurn":false,
            "requestSource":"background-revival",
            "skipAckObligation":true,
            "directAddressedAcceptance":true,
        });
        if let Err(error) = self.queue_chat_turn(
            &operation_id,
            command.get("requestId").and_then(Value::as_str).unwrap_or_default(),
            &command,
            bearer_token,
        ) {
            self.active_operations.remove(&operation_id);
            self.agent_turn_interruptions.unregister_operation(&operation_id);
            return Err(error);
        }
        for work_id in work_ids {
            self.pending_wake_store.clear_one(
                account_fence,
                agent_id,
                PendingWakeKind::Subagent,
                work_id,
            );
        }
        Ok(session_mutation)
    }

    fn drain_subagent_completion_revival_once(&mut self) -> Result<(), String> {
        self.sync_subagent_completion_wakes()?;
        let account_fence = match self.current_turn_account_fence() {
            Ok(value) => value,
            Err(_) => return Ok(()),
        };
        let markers = self
            .pending_wake_store
            .list_pending_for_account(&account_fence);
        let Some(first) = markers
            .iter()
            .find(|marker| marker.kind == PendingWakeKind::Subagent)
            .cloned()
        else {
            return Ok(());
        };
        let agent_id = first.agent_id.clone();
        let mut completions = Vec::new();
        let mut work_ids = Vec::new();
        {
            let owner = self
                .subagent_owner
                .lock()
                .map_err(|_| "durable subagent owner lock poisoned".to_string())?;
            for marker in markers.into_iter().filter(|marker| {
                marker.kind == PendingWakeKind::Subagent && marker.agent_id == agent_id
            }) {
                let Some(record) = owner.get(&marker.work_id).cloned() else {
                    continue;
                };
                if record.account_fence != account_fence
                    || !matches!(
                        record.status,
                        crate::runner::SubagentStatus::Completed
                            | crate::runner::SubagentStatus::Failed
                    )
                {
                    continue;
                }
                let status = if record.status == crate::runner::SubagentStatus::Failed {
                    "error"
                } else {
                    "success"
                };
                let result = record
                    .completion_result
                    .clone()
                    .or(record.completion_error.clone())
                    .unwrap_or_else(|| "(the background task settled without detail)".into());
                completions.push(SubagentCompletion {
                    parent_agent_id: record.parent_agent_id.clone(),
                    subagent_agent_id: record.subagent_id.clone(),
                    title: record.title.clone(),
                    subagent_type: record.subagent_type.clone(),
                    status: status.into(),
                    result,
                    quiet_origin: record
                        .quiet_origin
                        .as_ref()
                        .map(|_| QuietWakeOrigin { automation: None }),
                });
                work_ids.push(record.subagent_id);
            }
        }
        if completions.is_empty() {
            return Ok(());
        }

        // Transient auth/provider/queue failures retain every durable marker. The next receive
        // cycle retries the same deterministic request id.
        let _ = self.queue_subagent_completion_revival(
            &account_fence,
            &agent_id,
            &completions,
            &work_ids,
        );
        Ok(())
    }

    fn queue_box_handoff_resume_turn(
        &mut self,
        account_fence: &str,
        agent_id: &str,
        handoff_request_id: &str,
        trigger: &str,
    ) -> Result<Option<AccountSessionMutation>, String> {
        let trigger = trigger.trim();
        let request_id = format!(
            "box-handoff-resume:{}:{}:{}",
            handoff_request_id,
            agent_id,
            if trigger.is_empty() { "returned" } else { trigger },
        );

        // The durable turn journal is the idempotency authority. If a prior process queued this
        // exact continuation but died before acknowledging the handoff obligation, never queue a
        // second model turn: the original outcome is already owned by the journal.
        if self
            .turn_journal
            .lock()
            .map_err(|_| "turn journal lock poisoned".to_string())?
            .record(&request_id)
            .is_some()
        {
            self.box_handoff
                .lock()
                .map_err(|_| "Android box handoff lock poisoned".to_string())?
                .acknowledge_resume(account_fence, agent_id, handoff_request_id)?;
            return Ok(None);
        }

        let operation_id = self.next_operation_id(&request_id);
        self.active_operations.insert(operation_id.clone());
        let (bearer_token, session_mutation) = match self.bearer_token_for_turn() {
            Ok(value) => value,
            Err(error) => {
                self.active_operations.remove(&operation_id);
                return Err(error);
            }
        };
        let command = json!({
            "type":"chat.send",
            "requestId":request_id,
            "agentId":agent_id,
            "text":Self::box_handoff_resume_prompt(trigger),
            "hidden":true,
            "appendUserMessage":false,
            "awaitTurn":false,
            "requestSource":"handoff-resume",
            "skipAckObligation":true,
            "directAddressedAcceptance":true,
        });
        if let Err(error) = self.queue_chat_turn(
            &operation_id,
            command.get("requestId").and_then(Value::as_str).unwrap_or_default(),
            &command,
            bearer_token,
        ) {
            self.active_operations.remove(&operation_id);
            self.agent_turn_interruptions.unregister_operation(&operation_id);
            return Err(error);
        }
        self.box_handoff
            .lock()
            .map_err(|_| "Android box handoff lock poisoned".to_string())?
            .acknowledge_resume(account_fence, agent_id, handoff_request_id)?;
        Ok(session_mutation)
    }

    fn drain_box_handoff_resume_once(&mut self) -> Result<(), String> {
        let account_fence = match self.current_turn_account_fence() {
            Ok(value) => value,
            Err(_) => return Ok(()),
        };
        let pending = self
            .box_handoff
            .lock()
            .map_err(|_| "Android box handoff lock poisoned".to_string())?
            .pending_resumes_for_account(&account_fence)?;
        let Some(ended) = pending.into_iter().next() else {
            return Ok(());
        };

        // A transient credential/provider failure must not retire the durable obligation. The
        // next receive/cold-start cycle retries it, while queue_box_handoff_resume_turn fences
        // already-journaled continuations from duplicate execution.
        let _ = self.queue_box_handoff_resume_turn(
            &account_fence,
            &ended.agent_id,
            &ended.request_id,
            &ended.trigger,
        );
        Ok(())
    }

    fn agent_handoff_status(&self, params: &Value) -> Result<Value, String> {
        let account_fence = self.current_turn_account_fence()?;
        let agent_id = required_string(params, "agentId")?;
        self.box_handoff
            .lock()
            .map_err(|_| "Android box handoff lock poisoned".to_string())?
            .projection(&account_fence, agent_id)
    }

    fn agent_handoff_start(&mut self, params: &Value) -> Result<Value, String> {
        let account_fence = self.current_turn_account_fence()?;
        let agent_id = required_string(params, "agentId")?;
        let instruction = required_string(params, "instruction")?;
        let started = self
            .box_handoff
            .lock()
            .map_err(|_| "Android box handoff lock poisoned".to_string())?
            .start(&account_fence, agent_id, instruction, now_ms())?;
        Ok(match started {
            AndroidHandoffStart::Started(pending) => json!({
                "status": "started",
                "requestId": pending.request_id,
                "instruction": pending.instruction,
                "reason": pending.reason,
                "domain": pending.domain,
                "idpDomain": pending.idp_domain,
                "snapshotDataUrl": pending.snapshot_data_url,
                "createdAtMs": pending.created_at_ms,
            }),
            AndroidHandoffStart::AlreadyPending(pending) => json!({
                "status": "already-pending",
                "requestId": pending.request_id,
                "instruction": pending.instruction,
                "reason": pending.reason,
                "domain": pending.domain,
                "idpDomain": pending.idp_domain,
                "snapshotDataUrl": pending.snapshot_data_url,
                "createdAtMs": pending.created_at_ms,
            }),
        })
    }

    fn agent_handoff_attach_snapshot(&mut self, params: &Value) -> Result<Value, String> {
        let account_fence = self.current_turn_account_fence()?;
        let agent_id = required_string(params, "agentId")?;
        let request_id = required_string(params, "requestId")?;
        let snapshot_data_url = required_string(params, "snapshotDataUrl")?;
        let attached = self
            .box_handoff
            .lock()
            .map_err(|_| "Android box handoff lock poisoned".to_string())?
            .attach_snapshot_if_current(
                &account_fence,
                agent_id,
                request_id,
                snapshot_data_url,
            )?;
        Ok(json!({"attached": attached, "requestId": request_id}))
    }

    fn agent_handoff_end(&mut self, params: &Value) -> Result<Value, String> {
        let account_fence = self.current_turn_account_fence()?;
        let agent_id = required_string(params, "agentId")?;
        let request_id = required_string(params, "requestId")?;
        let ended = self
            .box_handoff
            .lock()
            .map_err(|_| "Android box handoff lock poisoned".to_string())?
            .end(
                &account_fence,
                agent_id,
                request_id,
                params.get("resolution").and_then(Value::as_str),
                params.get("trigger").and_then(Value::as_str),
            )?;
        Ok(match ended {
            Some(ended) => {
                self.turn_lifecycle
                    .lock()
                    .map_err(|_| "turn lifecycle lock poisoned".to_string())?
                    .clear_awaiting_user_for_agent_response(&account_fence, &ended.agent_id)?;
                let resume_mutation = self.queue_box_handoff_resume_turn(
                    &account_fence,
                    &ended.agent_id,
                    &ended.request_id,
                    &ended.trigger,
                )?;
                with_account_session_mutation(
                    json!({
                        "ended": true,
                        "requestId": ended.request_id,
                        "resolution": ended.resolution,
                        "trigger": ended.trigger,
                        "resumeQueued": true,
                    }),
                    resume_mutation,
                )
            }
            None => json!({"ended": false, "requestId": request_id}),
        })
    }

    fn memory_list(&self, params: &Value) -> Result<Value, String> {
        let account_fence = self.current_turn_account_fence()?;
        let agent_id = required_string(params, "agentId")?;
        self.memory
            .list(&account_fence, agent_id, params.get("limit").and_then(Value::as_u64))
    }

