    #[test]
    fn subagent_completion_wake_moves_to_durable_store_and_journal_before_marker_clear() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let parent = host
            .dispatch("createAgent", &json!({"name":"Parent","description":"revival parent"}))
            .unwrap();
        let parent_id = parent["agent"]["id"].as_str().unwrap().to_string();
        let account_fence = host.current_turn_account_fence().unwrap();
        let launch = host
            .subagent_owner
            .lock()
            .unwrap()
            .launch(
                &parent_id,
                SubagentLineage::default(),
                "box",
                "general-purpose",
                "revival-tool-call",
                "background work",
                &account_fence,
                Some("automation"),
                SubagentFrozenTurnConfig {
                    provider_id: "android-host-inference".into(),
                    model_id: "default".into(),
                    tool_names: Vec::new(),
                    allowed_subagent_types: vec!["general-purpose".into()],
                    privacy_mode: "no-storage".into(),
                    summarization_binding_id: "android-host-inference:same-provider".into(),
                },
                10,
            )
            .unwrap();
        let epoch = host.subagent_owner.lock().unwrap().process_epoch();
        host.subagent_owner
            .lock()
            .unwrap()
            .settle(
                &launch.record.subagent_id,
                &account_fence,
                epoch,
                SubagentRunOutcome::Completed("finished result".into()),
                11,
            )
            .unwrap();
        assert_eq!(
            host.subagent_owner
                .lock()
                .unwrap()
                .pending_completion_wakes_for_account(&account_fence)
                .len(),
            1
        );

        host.sync_subagent_completion_wakes().unwrap();
        assert!(
            host.subagent_owner
                .lock()
                .unwrap()
                .pending_completion_wakes_for_account(&account_fence)
                .is_empty(),
            "canonical completion obligation is acknowledged only after durable marker acceptance",
        );
        let marker = host
            .pending_wake_store
            .list_pending_for(&account_fence, &parent_id);
        assert_eq!(marker.len(), 1);
        assert_eq!(marker[0].work_id, launch.record.subagent_id);
        assert!(marker[0].quiet_origin.is_some());

        let request_id = AndroidJsonHost::subagent_revival_request_id(
            &parent_id,
            &[launch.record.subagent_id.clone()],
        );
        host.drain_subagent_completion_revival_once().unwrap();
        assert!(
            host.turn_journal.lock().unwrap().record(&request_id).is_some(),
            "durable turn journal must accept revival before wake marker is cleared",
        );
        assert!(
            host.pending_wake_store
                .list_pending_for(&account_fence, &parent_id)
                .is_empty(),
        );
        let _ = std::fs::remove_dir_all(root.path());
    }

    #[test]
    fn async_tasks_pending_wakes_are_durable_and_account_fenced() {
        use crate::extensions::transcript::sand_pending_wake_store::{
            DurablePendingWakeMarker, PendingWakeKind,
        };

        let root = std::env::temp_dir().join(format!(
            "fabushi-agent-async-pending-wake-{}",
            now_ms()
        ));
        let mut host = AndroidJsonHost::new(&root, AndroidHostMode::Test);
        host.logged_in = true;
        let account_fence = host.current_turn_account_fence().unwrap();
        let fresh_marked_at = now_ms();
        assert!(host.pending_wake_store.mark_pending(DurablePendingWakeMarker {
            account_fence: account_fence.clone(),
            agent_id: "agent-a".into(),
            kind: PendingWakeKind::Shell,
            work_id: "shell-a".into(),
            marked_at_ms: fresh_marked_at,
            quiet_origin: None,
            title: Some("Long build".into()),
            subagent_type: None,
            interrupted_by_recreate: true,
        }));
        assert!(host.pending_wake_store.mark_pending(DurablePendingWakeMarker {
            account_fence: "other-account:epoch-9".into(),
            agent_id: "agent-a".into(),
            kind: PendingWakeKind::CloudAgent,
            work_id: "cloud-secret".into(),
            marked_at_ms: fresh_marked_at,
            quiet_origin: None,
            title: None,
            subagent_type: None,
            interrupted_by_recreate: false,
        }));
        assert!(host.pending_wake_store.mark_pending(DurablePendingWakeMarker {
            account_fence: account_fence.clone(),
            agent_id: "agent-a".into(),
            kind: PendingWakeKind::Shell,
            work_id: "stale-shell".into(),
            marked_at_ms: fresh_marked_at.saturating_sub(PENDING_WAKE_STALE_MAX_AGE_MS + 1),
            quiet_origin: None,
            title: Some("Stale build".into()),
            subagent_type: None,
            interrupted_by_recreate: false,
        }));

        let value = host
            .agent_async_tasks(&json!({"id":"agent-a"}))
            .expect("same-account async task projection");
        let tasks = value.as_array().unwrap();
        assert_eq!(tasks.len(), 1);
        assert_eq!(tasks[0]["kind"], "shell");
        assert_eq!(tasks[0]["id"], "shell-a");
        assert_eq!(tasks[0]["label"], "Long build");
        assert_eq!(tasks[0]["detail"], "reattached after a host restart");
        let pending_wake_records = host
            .structured_log_spool
            .lock()
            .unwrap()
            .batch()
            .into_iter()
            .filter(|record| record.message == "sand.pending_wake")
            .collect::<Vec<_>>();
        assert_eq!(pending_wake_records.len(), 1);
        assert_eq!(pending_wake_records[0].metadata["conversation_id"], "agent-a");
        assert_eq!(pending_wake_records[0].metadata["outcome"], "pruned");
        assert_eq!(pending_wake_records[0].metadata["kind"], "shell");
        assert_eq!(pending_wake_records[0].metadata["work_id"], "stale-shell");
        assert_eq!(pending_wake_records[0].metadata["reason"], "stale");

        drop(host);
        let mut reopened = AndroidJsonHost::new(&root, AndroidHostMode::Test);
        reopened.logged_in = true;
        assert_eq!(
            reopened
                .pending_wake_store
                .list_pending_for(&account_fence, "agent-a")
                .len(),
            1
        );
        assert_eq!(
            reopened
                .pending_wake_store
                .list_pending_for("other-account:epoch-9", "agent-a")
                .len(),
            1,
            "projection pruning must not delete another account's durable marker",
        );
        let _ = std::fs::remove_dir_all(root);
    }

