    #[test]
    fn react_to_message_routed_tool_updates_canonical_transcript_once_per_call() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let account_fence = host.current_turn_account_fence().unwrap();
        host.transcript.lock().unwrap().append_entry(json!({
            "id":"t3u",
            "kind":"message",
            "role":"user",
            "content":"ship it",
            "agentId":"mahayana-assistant",
            "accountFence":account_fence,
        })).unwrap();
        let accepted = host.dispatch(
            "feature.execute",
            &json!({"command":{
                "type":"chat.send",
                "requestId":"reaction-root-request",
                "agentId":"mahayana-assistant",
                "model":"default",
                "text":"[[tool:ReactToMessage]] {\"message_address\":\"t3u\",\"emoji\":\"👍\"}"
            }}),
        ).unwrap();
        let operation_id = accepted["operationId"].as_str().unwrap().to_string();
        let deadline = std::time::Instant::now() + Duration::from_secs(3);
        loop {
            let event = host.dispatch("feature.receive", &json!({})).unwrap();
            if event["operationId"] == operation_id && event["type"] == "operation.completed" {
                break;
            }
            if event["operationId"] == operation_id && event["type"] == "operation.failed" {
                panic!("ReactToMessage root routed tool failed: {event}");
            }
            assert!(std::time::Instant::now() < deadline, "reaction turn must settle");
            if event.as_object().is_some_and(|object| object.is_empty()) {
                thread::sleep(Duration::from_millis(10));
            }
        }
        let reacted = host.transcript.lock().unwrap().entry("t3u").unwrap();
        assert_eq!(reacted["reactions"], json!([{"emoji":"👍","by":"me"}]));
    }

    #[test]
    fn request_box_help_is_not_exposed_without_remote_desktop_capability() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let mut command = json!({
            "type":"chat.send",
            "requestId":"box-help-no-desktop",
            "agentId":"mahayana-assistant",
            "model":"default",
            "text":"[[tool:request_box_help]] {\"instruction\":\"Complete sign-in\"}"
        });
        command[COORDINATOR_SUBAGENT_CAPABILITIES_FIELD] = json!({
            "multitaskEnabled":false,
            "remoteBoxAvailable":true,
            "remoteBoxHasDesktop":false,
            "browserUseEnabled":false
        });
        let accepted = host
            .dispatch("feature.execute", &json!({"command":command}))
            .unwrap();
        let operation_id = accepted["operationId"].as_str().unwrap().to_string();
        let deadline = std::time::Instant::now() + Duration::from_secs(3);
        loop {
            let event = host.dispatch("feature.receive", &json!({})).unwrap();
            if event["type"] == "operation.failed" && event["operationId"] == operation_id {
                break;
            }
            assert!(
                !(event["type"] == "operation.interrupted" && event["operationId"] == operation_id),
                "box help must not park when remote desktop capability is absent"
            );
            assert!(std::time::Instant::now() < deadline, "turn must settle");
            if event.as_object().is_some_and(|object| object.is_empty()) {
                thread::sleep(Duration::from_millis(10));
            }
        }
        let fence = host.current_turn_account_fence().unwrap();
        assert!(host
            .box_handoff
            .lock()
            .unwrap()
            .pending_for(&fence, "mahayana-assistant")
            .unwrap()
            .is_none());
    }

    #[test]
    fn request_box_help_routed_tool_parks_turn_and_resumes_once_after_handback() {
        let root_owner = tempfile::tempdir().unwrap();
        let root = root_owner.path();
        let mut host = AndroidJsonHost::new(root, AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let account_fence = host.current_turn_account_fence().unwrap();
        let mut command = json!({
            "type":"chat.send",
            "requestId":"box-help-root-request",
            "agentId":"mahayana-assistant",
            "model":"default",
            "text":"[[tool:request_box_help]] {\"instruction\":\"Complete account sign-in\",\"reason\":\"auth\",\"domain\":\"https://www.example.com/login\",\"idp_domain\":\"accounts.example.com\"}"
        });
        command[COORDINATOR_SUBAGENT_CAPABILITIES_FIELD] = json!({
            "multitaskEnabled":false,
            "remoteBoxAvailable":true,
            "remoteBoxHasDesktop":true,
            "browserUseEnabled":false
        });
        let accepted = host
            .dispatch("feature.execute", &json!({"command":command}))
            .unwrap();
        let operation_id = accepted["operationId"].as_str().unwrap().to_string();

        let deadline = std::time::Instant::now() + Duration::from_secs(3);
        let handoff_request_id = loop {
            let event = host.dispatch("feature.receive", &json!({})).unwrap();
            if event["type"] == "operation.interrupted"
                && event["operationId"] == operation_id
                && event["reason"] == "waiting-user"
            {
                break event["handoffRequestId"].as_str().unwrap().to_string();
            }
            if event["type"] == "operation.failed" && event["operationId"] == operation_id {
                panic!("request_box_help must park rather than fail: {event}");
            }
            assert!(std::time::Instant::now() < deadline, "box help turn must park");
            if event.as_object().is_some_and(|object| object.is_empty()) {
                thread::sleep(Duration::from_millis(10));
            }
        };

        let pending = host
            .box_handoff
            .lock()
            .unwrap()
            .pending_for(&account_fence, "mahayana-assistant")
            .unwrap()
            .unwrap();
        assert_eq!(pending.request_id, handoff_request_id);
        assert_eq!(pending.reason.as_deref(), Some("auth"));
        assert_eq!(pending.domain.as_deref(), Some("example.com"));
        assert_eq!(pending.idp_domain.as_deref(), Some("accounts.example.com"));
        let waiting = host
            .turn_lifecycle
            .lock()
            .unwrap()
            .awaiting_user_projection(&account_fence, "mahayana-assistant")
            .expect("handoff must project durable awaiting-user state");
        assert_eq!(waiting.operation_id, operation_id);
        assert!(waiting.reason.starts_with(WAITING_USER_CANCELLATION_PREFIX));
        let record = host
            .turn_journal
            .lock()
            .unwrap()
            .record("box-help-root-request")
            .cloned()
            .unwrap();
        assert_eq!(record.state, DurableTurnState::Cancelled);
        assert!(record.reason.as_deref().unwrap().starts_with(WAITING_USER_CANCELLATION_PREFIX));

        drop(host);
        let mut reopened = AndroidJsonHost::new(root, AndroidHostMode::Test);
        sign_in_test_account(&mut reopened);
        let reopened_fence = reopened.current_turn_account_fence().unwrap();
        assert!(reopened
            .box_handoff
            .lock()
            .unwrap()
            .pending_for(&reopened_fence, "mahayana-assistant")
            .unwrap()
            .is_some());
        assert!(reopened
            .turn_lifecycle
            .lock()
            .unwrap()
            .awaiting_user_projection(&reopened_fence, "mahayana-assistant")
            .unwrap()
            .recovery_required);

        let ended = reopened
            .dispatch(
                "feature.agent.handoff.end",
                &json!({
                    "agentId":"mahayana-assistant",
                    "requestId":handoff_request_id,
                    "resolution":"completed",
                    "trigger":"user-returned"
                }),
            )
            .unwrap();
        assert_eq!(ended["ended"], true);
        assert_eq!(ended["resumeQueued"], true);
        assert!(reopened
            .turn_lifecycle
            .lock()
            .unwrap()
            .awaiting_user_projection(&reopened_fence, "mahayana-assistant")
            .is_none());

        let resume_request_id =
            format!("box-handoff-resume:{handoff_request_id}:mahayana-assistant:user-returned");
        let resume_deadline = std::time::Instant::now() + Duration::from_secs(3);
        loop {
            if reopened
                .turn_journal
                .lock()
                .unwrap()
                .record(&resume_request_id)
                .is_some()
            {
                break;
            }
            assert!(std::time::Instant::now() < resume_deadline, "handoff continuation must queue");
            thread::sleep(Duration::from_millis(10));
        }
        assert!(reopened
            .box_handoff
            .lock()
            .unwrap()
            .pending_resumes_for_account(&reopened_fence)
            .unwrap()
            .is_empty());
    }

    #[test]
    fn production_turn_lifecycle_is_wired_into_android_chat_dispatch() {
        let root = std::env::temp_dir().join(format!(
            "fabushi-agent-lifecycle-wiring-{}",
            now_ms()
        ));
        let mut host = AndroidJsonHost::new(&root, AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let agent = host
            .agents
            .lock()
            .unwrap()
            .create("Lifecycle Agent", "profile")
            .unwrap();
        let account_fence = host.current_turn_account_fence().unwrap();

        host.dispatch(
            "feature.agent.diskPressure.record",
            &json!({
                "conversationId":agent.id.clone(),
                "episodeId":"disk-episode-1"
            }),
        )
        .unwrap();

        let accepted = host
            .dispatch(
                "feature.execute",
                &json!({
                    "command":{
                        "type":"chat.send",
                        "requestId":"lifecycle-request-1",
                        "agentId":agent.id.clone(),
                        "model":"default",
                        "text":"hello"
                    }
                }),
            )
            .unwrap();
        let operation_id = accepted["operationId"].as_str().unwrap().to_string();

        let mut completed = false;
        for _ in 0..64 {
            let event = host.dispatch("feature.receive", &json!({})).unwrap();
            if event["type"] == "operation.completed"
                && event["operationId"] == operation_id
            {
                completed = true;
                break;
            }
        }
        assert!(completed, "test provider turn must reach one terminal completion");
        let unread = host.agents.lock().unwrap().get(&agent.id).unwrap();
        assert!(unread.has_unread, "completed assistant turn must durably mark the Agent unread");
        assert_eq!(unread.unread_count, 1);
        let unread_activity_at = unread.last_activity_at;
        assert!(unread_activity_at > 0);

        assert_eq!(
            host.turn_lifecycle
                .lock()
                .unwrap()
                .claim_disk_pressure(
                    &account_fence,
                    &agent.id,
                    "probe-after-completion",
                    now_ms(),
                )
                .unwrap(),
            None,
            "successful production owner must commit rather than release the reminder claim"
        );
        let current_agent = host
            .agents
            .lock()
            .unwrap()
            .get(&agent.id)
            .expect("completed turn keeps canonical Agent");
        let revision = crate::sha256::sha256_hex(
            format!(
                "{}\n{}\n{}",
                current_agent.id,
                current_agent.name,
                current_agent.description
            )
            .as_bytes(),
        );
        assert!(!host
            .turn_lifecycle
            .lock()
            .unwrap()
            .profile_announcement_needed(&account_fence, &agent.id, &revision));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn cold_start_recovers_torn_visible_ack_without_reappending_user_message() {
        let root = std::env::temp_dir().join(format!(
            "fabushi-visible-ack-torn-recovery-{}-{}",
            std::process::id(),
            now_ms()
        ));
        let account_fence;
        {
            let mut host = AndroidJsonHost::new(&root, AndroidHostMode::Test);
            sign_in_test_account(&mut host);
            account_fence = host.current_turn_account_fence().unwrap();
            host.transcript
                .lock()
                .unwrap()
                .append_entry(json!({
                    "id":"torn-user-echo",
                    "kind":"message",
                    "role":"user",
                    "agentId":"mahayana-assistant",
                    "operationId":"torn-operation",
                    "accountFence":account_fence.clone(),
                    "clientNonce":"torn-client-nonce",
                    "content":"persisted before process death",
                    "timestampMs":10_u64,
                }))
                .unwrap();
            assert!(
                host.visible_ack_obligations
                    .pending_for_account(&account_fence)
                    .is_empty(),
                "fixture must model process death before acknowledgement obligation persistence",
            );
        }

        let mut reopened = AndroidJsonHost::new(&root, AndroidHostMode::Test);
        sign_in_test_account(&mut reopened);
        let pending = reopened
            .visible_ack_obligations
            .pending_for_account(&account_fence);
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].agent_id, "mahayana-assistant");
        let entries = reopened.transcript.lock().unwrap().get_transcript();
        assert_eq!(
            entries
                .iter()
                .filter(|entry| entry.get("id").and_then(Value::as_str) == Some("torn-user-echo"))
                .count(),
            1,
            "cold-start reconciliation must never reappend the accepted user message",
        );
        assert!(
            entries.iter().all(|entry| {
                entry.get("id").and_then(Value::as_str) != Some("assistant:torn-operation")
            }),
            "reconciliation must restore the obligation, never fabricate assistant completion",
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn visible_ack_redrive_lost_agent_records_structured_telemetry() {
        let root = std::env::temp_dir().join(format!(
            "fabushi-visible-ack-lost-agent-{}-{}",
            std::process::id(),
            now_ms()
        ));
        let mut host = AndroidJsonHost::new(&root, AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let account_fence = host.current_turn_account_fence().unwrap();
        host.structured_log_shipping.store(true, Ordering::Release);
        host.visible_ack_obligations
            .record_send(&account_fence, "deleted-agent", 1.0)
            .unwrap();
        assert!(host
            .visible_ack_obligations
            .schedule_after_idle(&account_fence, "deleted-agent", 0));

        host.drain_visible_ack_redrive_once().unwrap();

        assert!(host
            .visible_ack_obligations
            .pending_for_account(&account_fence)
            .is_empty());
        let records = host.structured_log_spool.lock().unwrap().batch();
        let event = records
            .iter()
            .find(|record| record.message == "sand.ack.obligation")
            .expect("lost visible-ack recovery must emit structured telemetry");
        assert_eq!(event.level, "warn");
        assert_eq!(
            event.metadata.get("conversation_id").map(String::as_str),
            Some("deleted-agent")
        );
        assert_eq!(
            event.metadata.get("outcome").map(String::as_str),
            Some("lost")
        );
        assert_eq!(
            event.metadata.get("reason").map(String::as_str),
            Some("agent_deleted")
        );
        let _ = std::fs::remove_dir_all(root);
    }

