#[cfg(test)]
mod plugin_release_lifecycle_tests {
    use super::*;

    #[test]
    fn update_requires_install_and_uninstall_is_idempotent() {
        let root = std::env::temp_dir().join(format!("fabushi-plugin-lifecycle-{}", now_ms()));
        let mut host = AndroidJsonHost::new(&root, AndroidHostMode::Test);
        let release = json!({"pluginId":"lifecycle-plugin"});
        assert!(host
            .dispatch("feature.plugin.update", &json!({"release":release.clone()}))
            .unwrap_err()
            .contains("plugin is not installed"));
        host.dispatch("feature.plugin.install", &json!({"release":release.clone()}))
            .unwrap();
        assert_eq!(
            host.dispatch("feature.plugin.update", &json!({"release":release}))
                .unwrap()["updated"],
            true
        );
        assert_eq!(
            host.dispatch(
                "feature.plugin.uninstall",
                &json!({"pluginId":"lifecycle-plugin"}),
            )
            .unwrap()["removed"],
            true
        );
        assert!(host
            .dispatch("plugin.compatibility", &json!({"pluginId":"lifecycle-plugin"}))
            .unwrap_err()
            .contains("plugin is not installed"));
        assert_eq!(
            host.dispatch(
                "feature.plugin.uninstall",
                &json!({"pluginId":"lifecycle-plugin"}),
            )
            .unwrap()["removed"],
            false
        );
        let _ = std::fs::remove_dir_all(root);
    }
}

#[cfg(test)]
mod widget_action_tests {
    use super::*;

    fn widget_entry(id: &str, agent_id: &str, allow_custom: bool) -> Value {
        json!({
            "id":id,
            "kind":"send-message",
            "agentId":agent_id,
            "message":{
                "type":"widget",
                "widget":{
                    "prompt":"Choose",
                    "options":[
                        {"label":"Alpha","value":"a"},
                        {"label":"Beta"}
                    ],
                    "allowCustom":allow_custom
                }
            }
        })
    }

    #[test]
    fn widget_response_and_dismiss_persist_canonically_and_reject_stale_or_settled_actions() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        host.transcript
            .lock()
            .unwrap()
            .append_entry(widget_entry("widget-a", "agent-a", false))
            .unwrap();
        host.transcript
            .lock()
            .unwrap()
            .append_entry(widget_entry("widget-b", "agent-a", true))
            .unwrap();

        assert!(host
            .dispatch(
                "feature.widget.respond",
                &json!({"agentId":"agent-b","entryId":"widget-a","value":"a"})
            )
            .is_err());
        let invalid = host
            .dispatch(
                "feature.widget.respond",
                &json!({"agentId":"agent-a","entryId":"widget-a","value":"custom"})
            )
            .unwrap();
        assert_eq!(invalid["accepted"], false);
        let accepted = host
            .dispatch(
                "feature.widget.respond",
                &json!({"agentId":"agent-a","entryId":"widget-a","value":"a"})
            )
            .unwrap();
        assert_eq!(accepted["accepted"], true);
        let duplicate = host
            .dispatch(
                "feature.widget.respond",
                &json!({"agentId":"agent-a","entryId":"widget-a","value":"a"})
            )
            .unwrap();
        assert_eq!(duplicate["accepted"], false);

        let dismissed = host
            .dispatch(
                "feature.widget.dismiss",
                &json!({"agentId":"agent-a","entryId":"widget-b"})
            )
            .unwrap();
        assert_eq!(dismissed["accepted"], true);

        drop(host);
        let mut reopened = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut reopened);
        let transcript = reopened
            .dispatch("feature.transcript.snapshot", &json!({}))
            .unwrap();
        let rows = transcript.as_array().unwrap();
        let answered = rows.iter().find(|row| row["id"] == "widget-a").unwrap();
        let dismissed = rows.iter().find(|row| row["id"] == "widget-b").unwrap();
        assert_eq!(answered["respondedValue"], "a");
        assert_eq!(dismissed["widgetDismissed"], true);
    }

    fn secret_request_entry(id: &str, agent_id: &str, account_fence: &str) -> Value {
        json!({
            "id":id,
            "kind":"send-message",
            "agentId":agent_id,
            "accountFence":account_fence,
            "message":{
                "type":"secret-request",
                "secretRequest":{
                    "label":" Discord bot token ",
                    "target":{
                        "kind":"channel-credential",
                        "platform":"discord",
                        "field":"token"
                    }
                }
            }
        })
    }

    #[test]
    fn secret_request_prepare_and_commit_are_account_fenced_durable_and_secret_free() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let fence = host.current_turn_account_fence().unwrap();
        host.transcript
            .lock()
            .unwrap()
            .append_entry(secret_request_entry("secret-a", "agent-a", &fence))
            .unwrap();

        assert!(host
            .dispatch(
                "feature.transcript.secret.prepare",
                &json!({"agentId":"agent-b","entryId":"secret-a","generation":7}),
            )
            .is_err());

        let prepared = host
            .dispatch(
                "feature.transcript.secret.prepare",
                &json!({
                    "agentId":"agent-a",
                    "entryId":"secret-a",
                    "generation":7,
                    "value":"secret-token-must-never-enter-native-transcript"
                }),
            )
            .unwrap();
        assert_eq!(prepared["accepted"], true);
        assert_eq!(prepared["accountFence"], fence);
        assert_eq!(prepared["platform"], "discord");
        assert_eq!(prepared["field"], "token");
        assert_eq!(prepared["label"], "Discord bot token");
        assert!(prepared.get("value").is_none());

        assert!(host
            .dispatch(
                "feature.transcript.secret.commit",
                &json!({
                    "agentId":"agent-a",
                    "entryId":"secret-a",
                    "generation":7,
                    "accountFence":"session:stale:android",
                    "platform":"discord",
                    "field":"token"
                }),
            )
            .is_err());

        let committed = host
            .dispatch(
                "feature.transcript.secret.commit",
                &json!({
                    "agentId":"agent-a",
                    "entryId":"secret-a",
                    "generation":7,
                    "accountFence":fence,
                    "platform":"discord",
                    "field":"token"
                }),
            )
            .unwrap();
        assert_eq!(committed["accepted"], true);
        assert_eq!(committed["secretProvided"], true);
        assert!(committed["operationId"]
            .as_str()
            .is_some_and(|value| !value.is_empty()));

        let duplicate_commit = host
            .dispatch(
                "feature.transcript.secret.commit",
                &json!({
                    "agentId":"agent-a",
                    "entryId":"secret-a",
                    "generation":7,
                    "accountFence":fence,
                    "platform":"discord",
                    "field":"token"
                }),
            )
            .unwrap();
        assert_eq!(duplicate_commit["accepted"], false);
        assert_eq!(duplicate_commit["reason"], "settled");
        assert_eq!(duplicate_commit["secretProvided"], true);
        assert!(duplicate_commit.get("operationId").is_none());

        let duplicate = host
            .dispatch(
                "feature.transcript.secret.prepare",
                &json!({"agentId":"agent-a","entryId":"secret-a","generation":8}),
            )
            .unwrap();
        assert_eq!(duplicate["accepted"], false);
        assert_eq!(duplicate["reason"], "settled");

        drop(host);
        let mut reopened = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut reopened);
        let snapshot = reopened
            .dispatch("feature.transcript.snapshot", &json!({}))
            .unwrap();
        let entry = snapshot
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["id"] == "secret-a")
            .unwrap();
        assert_eq!(entry["secretProvided"], true);
        let durable = std::fs::read_to_string(reopened.transcript.lock().unwrap().path()).unwrap();
        assert!(!durable.contains("secret-token-must-never-enter-native-transcript"));
    }

    #[test]
    fn agent_reaction_is_desired_state_durable_idempotent_and_account_fenced() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let fence = host.current_turn_account_fence().unwrap();
        host.transcript.lock().unwrap().append_entry(json!({
            "id":"assistant-reaction-a",
            "kind":"message",
            "role":"assistant",
            "agentId":"agent-a",
            "accountFence":fence,
            "content":"done"
        })).unwrap();

        let first = host.dispatch("feature.transcript.reaction.set", &json!({
            "agentId":"agent-a","entryId":"assistant-reaction-a","emoji":"👍","enabled":true,"generation":7
        })).unwrap();
        assert_eq!(first["accepted"], true);
        assert_eq!(first["changed"], true);
        assert_eq!(first["enabled"], true);

        let duplicate = host.dispatch("feature.transcript.reaction.set", &json!({
            "agentId":"agent-a","entryId":"assistant-reaction-a","emoji":"👍","enabled":true,"generation":7
        })).unwrap();
        assert_eq!(duplicate["changed"], false);
        assert_eq!(duplicate["entry"]["reactions"].as_array().unwrap().len(), 1);
        assert!(host.dispatch("feature.transcript.reaction.set", &json!({
            "agentId":"agent-b","entryId":"assistant-reaction-a","emoji":"👍","enabled":false,"generation":7
        })).is_err());

        let removed = host.dispatch("feature.transcript.reaction.set", &json!({
            "agentId":"agent-a","entryId":"assistant-reaction-a","emoji":"👍","enabled":false,"generation":8
        })).unwrap();
        assert_eq!(removed["changed"], true);
        assert!(removed["entry"].get("reactions").is_none());

        host.dispatch("feature.transcript.reaction.set", &json!({
            "agentId":"agent-a","entryId":"assistant-reaction-a","emoji":"🔥","enabled":true,"generation":9
        })).unwrap();
        drop(host);
        let mut reopened = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut reopened);
        let snapshot = reopened.dispatch("feature.transcript.snapshot", &json!({})).unwrap();
        let entry = snapshot.as_array().unwrap().iter().find(|row| row["id"] == "assistant-reaction-a").unwrap();
        assert_eq!(entry["reactions"][0]["emoji"], "🔥");
        assert_eq!(entry["reactions"][0]["by"], "me");
    }

    #[test]
    fn post_journal_approval_cleanup_is_canonical_and_failure_isolated() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);

        let pending = host
            .dispatch(
                "feature.execute",
                &json!({"command":{
                    "type":"capability.request",
                    "requestId":"approval-cleanup-old",
                    "capability":"camera"
                }}),
            )
            .unwrap();
        let old_operation = pending["operationId"].as_str().unwrap().to_string();
        let approval = (0..16)
            .find_map(|_| {
                let event = host.dispatch("feature.receive", &json!({})).ok()?;
                (event["type"] == "approval.requested"
                    && event["operationId"] == old_operation)
                    .then_some(event)
            })
            .expect("matching approval requested");
        let approval_id = approval["approvalId"].as_str().unwrap().to_string();

        let accepted = {
            let mut owner = host.send_acknowledgements.lock().unwrap();
            let record = owner
                .begin(
                    None,
                    "session:test:android",
                    "mahayana-assistant",
                    "cleanup-send-a",
                    "hello",
                    vec![SendAcknowledgementEntry {
                        id: "cleanup-send-a".into(),
                        kind: crate::send_acknowledgement::SendAcknowledgementEntryKind::Message,
                        client_nonce: "cleanup-send-a".into(),
                    }],
                )
                .unwrap();
            owner
                .mark_queued(
                    None,
                    "session:test:android",
                    "mahayana-assistant",
                    &record.nonce,
                    record.generation,
                )
                .unwrap();
            owner
                .mark_dispatching(
                    None,
                    "session:test:android",
                    "mahayana-assistant",
                    &record.nonce,
                    record.generation,
                )
                .unwrap();
            owner
                .mark_accepted(
                    None,
                    "session:test:android",
                    "mahayana-assistant",
                    &record.nonce,
                    record.generation,
                )
                .unwrap()
        };

        let cleared = host
            .dispatch(
                "feature.sendAcknowledgement.clearApprovals",
                &json!({
                    "agentId":"mahayana-assistant",
                    "nonce":accepted.nonce,
                    "generation":accepted.generation,
                    "approvalId":approval_id,
                    "approvalOperationId":old_operation,
                }),
            )
            .unwrap();
        assert_eq!(cleared["status"], "cleared");
        assert_eq!(cleared["cleared"], true);
        assert!(host
            .dispatch(
                "feature.approval.resolve",
                &json!({"approvalId":approval_id,"approved":true}),
            )
            .is_err());

        let next = host
            .dispatch(
                "feature.execute",
                &json!({"command":{
                    "type":"capability.request",
                    "requestId":"approval-cleanup-failure",
                    "capability":"microphone"
                }}),
            )
            .unwrap();
        let next_operation = next["operationId"].as_str().unwrap().to_string();
        let next_approval = (0..16)
            .find_map(|_| {
                let event = host.dispatch("feature.receive", &json!({})).ok()?;
                (event["type"] == "approval.requested"
                    && event["operationId"] == next_operation)
                    .then_some(event)
            })
            .expect("next matching approval requested");
        let next_approval_id = next_approval["approvalId"].as_str().unwrap().to_string();

        let failed_cleanup = host.dispatch(
            "feature.sendAcknowledgement.clearApprovals",
            &json!({
                "agentId":"mahayana-assistant",
                "nonce":accepted.nonce,
                "generation":accepted.generation,
                "approvalId":next_approval_id,
                "approvalOperationId":"wrong-operation",
            }),
        );
        assert!(failed_cleanup.is_err());
        assert_eq!(
            host.send_acknowledgements
                .lock()
                .unwrap()
                .record(
                    None,
                    "session:test:android",
                    "mahayana-assistant",
                    &accepted.nonce,
                )
                .unwrap()
                .phase,
            SendAcknowledgementPhase::AcceptedAwaitingEcho,
        );
        let denied = host
            .dispatch(
                "feature.approval.resolve",
                &json!({"approvalId":next_approval_id,"approved":false}),
            )
            .unwrap();
        assert_eq!(denied["operationId"], next_operation);
        assert_eq!(denied["execution"], "denied");

        let unaccepted = {
            let mut owner = host.send_acknowledgements.lock().unwrap();
            owner
                .begin(
                    None,
                    "session:test:android",
                    "mahayana-assistant",
                    "cleanup-send-pending",
                    "still pending",
                    vec![SendAcknowledgementEntry {
                        id: "cleanup-send-pending".into(),
                        kind: crate::send_acknowledgement::SendAcknowledgementEntryKind::Message,
                        client_nonce: "cleanup-send-pending".into(),
                    }],
                )
                .unwrap()
        };
        assert!(host
            .dispatch(
                "feature.sendAcknowledgement.clearApprovals",
                &json!({
                    "agentId":"mahayana-assistant",
                    "nonce":unaccepted.nonce,
                    "generation":unaccepted.generation,
                }),
            )
            .is_err());
    }

}

