#[cfg(test)]
mod android_box_handoff_runtime_tests {
    use super::*;

    #[test]
    fn handoff_resume_prompts_preserve_return_dismiss_and_uncertain_close_semantics() {
        assert!(AndroidJsonHost::box_handoff_resume_prompt("returned")
            .contains("handed the box back"));
        assert!(AndroidJsonHost::box_handoff_resume_prompt("dismissed")
            .contains("Treat it as declined"));
        let viewer_closed = AndroidJsonHost::box_handoff_resume_prompt("viewer-closed");
        assert!(viewer_closed.contains("may or may not have finished"));
        assert!(viewer_closed.contains("read-only Screenshot"));
    }

    #[test]
    fn durable_handoff_routes_survive_reopen_and_fence_late_results() {
        let root = tempfile::tempdir().unwrap();
        let request_id;
        {
            let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
            sign_in_test_account(&mut host);
            let started = host
                .dispatch(
                    "feature.agent.handoff.start",
                    &json!({"agentId":"agent-handoff","instruction":"Complete the remote login"}),
                )
                .unwrap();
            assert_eq!(started["status"], "started");
            request_id = started["requestId"].as_str().unwrap().to_string();

            let duplicate = host
                .dispatch(
                    "feature.agent.handoff.start",
                    &json!({"agentId":"agent-handoff","instruction":"Different instruction"}),
                )
                .unwrap();
            assert_eq!(duplicate["status"], "already-pending");
            assert_eq!(duplicate["requestId"], request_id);
            assert_eq!(duplicate["instruction"], "Complete the remote login");
        }

        {
            let mut reopened = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
            sign_in_test_account(&mut reopened);
            let status = reopened
                .dispatch(
                    "feature.agent.handoff.status",
                    &json!({"agentId":"agent-handoff"}),
                )
                .unwrap();
            assert_eq!(status["requestId"], request_id);

            let stale = reopened
                .dispatch(
                    "feature.agent.handoff.attachSnapshot",
                    &json!({
                        "agentId":"agent-handoff",
                        "requestId":"stale-request",
                        "snapshotDataUrl":"data:image/webp;base64,old"
                    }),
                )
                .unwrap();
            assert_eq!(stale["attached"], false);

            let attached = reopened
                .dispatch(
                    "feature.agent.handoff.attachSnapshot",
                    &json!({
                        "agentId":"agent-handoff",
                        "requestId":request_id,
                        "snapshotDataUrl":"data:image/webp;base64,new"
                    }),
                )
                .unwrap();
            assert_eq!(attached["attached"], true);

            let ended = reopened
                .dispatch(
                    "feature.agent.handoff.end",
                    &json!({
                        "agentId":"agent-handoff",
                        "requestId":request_id,
                        "resolution":"completed",
                        "trigger":"user"
                    }),
                )
                .unwrap();
            assert_eq!(ended["ended"], true);
            assert_eq!(ended["resumeQueued"], true);
            assert!(reopened
                .box_handoff
                .lock()
                .unwrap()
                .pending_resumes_for_account("session:test:android")
                .unwrap()
                .is_empty());
            let resume_request_id =
                format!("box-handoff-resume:{request_id}:agent-handoff:user");
            let resume = reopened
                .turn_journal
                .lock()
                .unwrap()
                .record(&resume_request_id)
                .cloned()
                .expect("handoff continuation must be durably queued before the obligation retires");
            assert_eq!(resume.request_source.as_deref(), Some("handoff-resume"));
        }

        let mut after_end = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut after_end);
        assert!(
            after_end
                .dispatch(
                    "feature.agent.handoff.status",
                    &json!({"agentId":"agent-handoff"}),
                )
                .unwrap()
                .is_null(),
            "terminal handoff must not resurrect after process reopen",
        );
    }

    #[test]
    fn journaled_handoff_resume_recovery_acknowledges_without_duplicate_turn() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let account_fence = host.current_turn_account_fence().unwrap();
        let started = host
            .box_handoff
            .lock()
            .unwrap()
            .start(&account_fence, "agent-replay", "Take over", now_ms())
            .unwrap();
        let AndroidHandoffStart::Started(started) = started else { panic!() };
        let ended = host
            .box_handoff
            .lock()
            .unwrap()
            .end(
                &account_fence,
                "agent-replay",
                &started.request_id,
                Some("completed"),
                Some("viewer-closed"),
            )
            .unwrap()
            .unwrap();
        let request_id = format!(
            "box-handoff-resume:{}:{}:{}",
            ended.request_id, ended.agent_id, ended.trigger
        );
        let generation = host
            .turn_journal
            .lock()
            .unwrap()
            .begin_with_context(
                &request_id,
                "already-queued-operation",
                &account_fence,
                Some("handoff-resume"),
                Some("agent-replay"),
                now_ms(),
            )
            .unwrap();
        host.drain_box_handoff_resume_once().unwrap();
        assert!(host
            .box_handoff
            .lock()
            .unwrap()
            .pending_resumes_for_account(&account_fence)
            .unwrap()
            .is_empty());
        assert_eq!(
            host.turn_journal.lock().unwrap().record(&request_id).unwrap().generation,
            generation,
            "recovery must acknowledge the existing durable continuation instead of queuing another"
        );
    }

    #[test]
    fn account_transition_cleanup_forgets_only_the_previous_handoff_fence() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        host.dispatch(
            "feature.agent.handoff.start",
            &json!({"agentId":"agent-old","instruction":"Old account work"}),
        )
        .unwrap();

        host.prepare_account_transition_cleanup("session:test:android", "account-switch")
            .unwrap();

        assert_eq!(host.box_handoff.lock().unwrap().pending_count(), 0);
        assert!(
            host.dispatch(
                "feature.agent.handoff.status",
                &json!({"agentId":"agent-old"}),
            )
            .unwrap()
            .is_null()
        );
    }
}

#[cfg(test)]
mod human_remote_sync_contract_tests {
    use super::*;

    #[test]
    fn remote_contact_normalization_is_account_safe_and_bounded() {
        let contacts = normalize_human_remote_contacts(
            &json!({"success":true,"data":{"friends":[
                {"id":"friend-row","userId":"peer-1","username":"peer","displayName":"Peer"},
                {"id":"self-row","userId":"self","username":"self","displayName":"Self"}
            ]}}),
            "human:self",
        )
        .unwrap();
        assert_eq!(contacts.len(), 1);
        assert_eq!(contacts[0]["id"], "human:peer-1");
        assert!(normalize_human_remote_contacts(
            &json!({"success":true,"data":{"friends":[
                {"userId":"dup","displayName":"One"},
                {"userId":"dup","displayName":"Two"}
            ]}}),
            "human:self",
        )
        .is_err());
    }

    #[test]
    fn remote_message_sync_path_is_bounded_and_percent_encoded() {
        assert_eq!(
            human_remote_messages_path("human:a/b c", Some("cursor/with space"), 999).unwrap(),
            "/api/social/messages?contactId=human%3Aa%2Fb%20c&limit=200&before=cursor%2Fwith%20space",
        );
        assert_eq!(
            human_remote_messages_path("human:peer", None, 0).unwrap(),
            "/api/social/messages?contactId=human%3Apeer&limit=1",
        );
        assert!(human_remote_messages_path("   ", None, 10).is_err());
        assert!(human_remote_messages_path("human:peer", Some(&"x".repeat(201)), 10).is_err());
    }

    #[test]
    fn remote_sync_rejects_backend_failure_envelopes() {
        assert!(validate_human_remote_envelope(
            &json!({"success":true,"data":{"friends":[]}}),
            "contact sync",
        ).is_ok());
        let error = validate_human_remote_envelope(
            &json!({"success":false,"error":"denied"}),
            "contact sync",
        ).unwrap_err();
        assert!(error.contains("denied"));
        assert!(validate_human_remote_envelope(&json!([]), "message sync").is_err());
    }
}


#[cfg(test)]
mod listener_connect_resume_runtime_tests {
    use super::*;

    #[test]
    fn reconnect_transition_queues_one_hidden_resume_and_acks_durable_watch() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let account_fence = host.current_turn_account_fence().unwrap();
        let agent = host.agents.lock().unwrap().create("Listener Agent", "").unwrap();
        let generation = host.listener_connect_watches
            .watch(&account_fence, &agent.id, "slack", now_ms())
            .unwrap();

        host.poll_listener_connect_watches().unwrap();
        let pending = host.listener_connect_watches
            .pending_for_account(&account_fence, now_ms())
            .unwrap();
        assert_eq!(pending.len(), 1);
        assert!(pending[0].armed);
        assert!(!pending[0].ready);

        host.agent_channel_store(&account_fence, &agent.id)
            .unwrap()
            .write_metadata("slack", "Ops")
            .unwrap();
        host.poll_listener_connect_watches().unwrap();
        let ready = host.listener_connect_watches.ready_for_account(&account_fence);
        assert_eq!(ready.len(), 1);
        assert_eq!(ready[0].generation, generation);
        let request_id = format!(
            "listener-connect-resume:{}:{}:slack:{}",
            crate::sha256::sha256_hex(account_fence.as_bytes()),
            agent.id,
            generation,
        );
        host.drain_listener_connect_resume_once().unwrap();
        let journal = host.turn_journal.lock().unwrap();
        let record = journal.record(&request_id).expect("hidden resume must enter durable turn journal");
        assert_eq!(record.request_source.as_deref(), Some("handoff-resume"));
        assert_eq!(record.agent_id.as_deref(), Some(agent.id.as_str()));
        drop(journal);
        assert!(host.listener_connect_watches.ready_for_account(&account_fence).is_empty());

        let first_generation = host
            .turn_journal
            .lock()
            .unwrap()
            .record(&request_id)
            .unwrap()
            .generation;
        host.drain_listener_connect_resume_once().unwrap();
        assert_eq!(
            host.turn_journal.lock().unwrap().record(&request_id).unwrap().generation,
            first_generation,
            "duplicate receive must not create a second durable resume generation",
        );
    }

    #[test]
    fn process_reopen_restores_armed_watch_and_account_fences_ready_completion() {
        let root = tempfile::tempdir().unwrap();
        let agent_id;
        let account_fence;
        {
            let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
            sign_in_test_account(&mut host);
            account_fence = host.current_turn_account_fence().unwrap();
            let agent = host.agents.lock().unwrap().create("Reconnect Agent", "").unwrap();
            agent_id = agent.id.clone();
            host.listener_connect_watches
                .watch(&account_fence, &agent_id, "github", now_ms())
                .unwrap();
            host.poll_listener_connect_watches().unwrap();
            assert!(host.listener_connect_watches
                .pending_for_account(&account_fence, now_ms()).unwrap()[0].armed);
        }

        let mut reopened = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut reopened);
        let reopened_fence = reopened.current_turn_account_fence().unwrap();
        assert_eq!(reopened_fence, account_fence, "same protected account must restore the same fence");
        reopened.agent_channel_store(&reopened_fence, &agent_id)
            .unwrap()
            .write_metadata("github", "GitHub")
            .unwrap();
        reopened.poll_listener_connect_watches().unwrap();
        assert_eq!(reopened.listener_connect_watches.ready_for_account(&reopened_fence).len(), 1);
        assert!(reopened.listener_connect_watches.ready_for_account("stale-account-fence").is_empty());
    }
}

#[cfg(test)]
mod host_event_bus_delivery_tests {
    use super::*;

    #[test]
    fn feature_receive_projects_canonical_event_without_competing_consumption() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let receiver = host.host_event_bus().subscribe();

        let accepted = host
            .dispatch(
                "feature.execute",
                &json!({"command":{
                    "type":"capability.request",
                    "requestId":"event-bus-capability-1",
                    "capability":"camera"
                }}),
            )
            .unwrap();
        assert_eq!(accepted["requestId"], "event-bus-capability-1");

        let started = host.dispatch("feature.receive", &json!({})).unwrap();
        assert_eq!(started["type"], "operation.started");
        let projected_started = receiver
            .recv_timeout(Duration::from_secs(1))
            .expect("started canonical event must be observable by HostEventBus");
        assert_eq!(projected_started.family, "operation.started");
        assert_eq!(
            serde_json::from_str::<Value>(&projected_started.payload_json).unwrap(),
            started,
            "HostEventBus must project the canonical started event without consuming it",
        );

        let canonical = host.dispatch("feature.receive", &json!({})).unwrap();
        assert_eq!(canonical["type"], "approval.requested");

        let projected = receiver
            .recv_timeout(Duration::from_secs(1))
            .expect("approval canonical event must be observable by HostEventBus");
        assert_eq!(projected.family, "approval.requested");
        assert_eq!(
            serde_json::from_str::<Value>(&projected.payload_json).unwrap(),
            canonical,
            "HostEventBus is a projection-only side channel, never a second canonical queue",
        );
    }
}

#[cfg(test)]
mod turn_interrupt_telemetry_wiring_tests {
    use super::*;

    #[test]
    fn cancelling_running_turn_persists_interrupt_telemetry_after_canonical_settlement() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        sign_in_test_account(&mut host);
        let account_fence = host.current_turn_account_fence().unwrap();
        let generation = host
            .turn_journal
            .lock()
            .unwrap()
            .begin_with_context(
                "request-interrupt",
                "operation-interrupt",
                &account_fence,
                Some("turn"),
                Some("agent-interrupt"),
                now_ms(),
            )
            .unwrap();
        host.active_operations.insert("operation-interrupt".into());

        host.cancel_operation("operation-interrupt", Some("user"))
            .unwrap();

        let record = host
            .turn_journal
            .lock()
            .unwrap()
            .record("request-interrupt")
            .cloned()
            .unwrap();
        assert_eq!(record.generation, generation);
        assert_eq!(record.state, DurableTurnState::Cancelled);
        assert_eq!(record.reason.as_deref(), Some("user"));
        assert!(!host.active_operations.contains("operation-interrupt"));

        let interrupt = host
            .structured_log_spool
            .lock()
            .unwrap()
            .snapshot()
            .checkpoint
            .records
            .into_iter()
            .find(|entry| entry.message == "sand.turn.interrupt")
            .expect("turn cancellation must persist Desktop-compatible interrupt telemetry");
        assert_eq!(
            interrupt.metadata.get("conversation_id").map(String::as_str),
            Some("agent-interrupt")
        );
        assert_eq!(interrupt.metadata.get("reason").map(String::as_str), Some("user"));
        assert_eq!(
            interrupt.metadata.get("had_active_run").map(String::as_str),
            Some("true")
        );
        assert_eq!(
            interrupt.metadata.get("was_in_flight").map(String::as_str),
            Some("true")
        );
    }

    #[test]
    fn cancelling_non_turn_operation_does_not_fabricate_turn_telemetry() {
        let root = tempfile::tempdir().unwrap();
        let mut host = AndroidJsonHost::new(root.path(), AndroidHostMode::Test);
        host.active_operations.insert("generic-operation".into());

        host.cancel_operation("generic-operation", Some("user")).unwrap();

        assert!(host
            .structured_log_spool
            .lock()
            .unwrap()
            .snapshot()
            .checkpoint
            .records
            .iter()
            .all(|entry| entry.message != "sand.turn.interrupt"));
    }
}

